package com.app.service;
import com.app.dto.SocietyDailyOperationsDtos.*; import com.app.entity.*; import com.app.exception.*; import com.app.repository.*; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class SocietyDailyOperationsService {
 private static final Set<String> SEVERITIES=Set.of("LOW","MEDIUM","HIGH","CRITICAL"), INCIDENT_STATUSES=Set.of("OPEN","INVESTIGATING","CLOSED"), RESULTS=Set.of("PASS","FAIL","NOT_APPLICABLE");
 private final AccountRepository accounts; private final UserRepository users; private final SocietyDailyChecklistTemplateRepository templates; private final SocietyDailyChecklistEntryRepository entries; private final SocietyIncidentRepository incidents; private final SocietyInspectionRepository inspections; private final SocietyShiftHandoverRepository handovers; private final SocietyDailyReportRepository reports; private final SocietyAttendanceRepository attendance; private final SocietyWorkOrderRepository workOrders; private final SocietyComplaintRepository complaints; private final SocietyAuditEventRepository audit; private final ObjectMapper json;
 @Transactional(readOnly=true) public List<ChecklistItemDto> checklist(Long aid,LocalDate date){society(aid);Map<Long,SocietyDailyChecklistEntry> byTemplate=entries.findByAccountIdAndOperationDate(aid,date).stream().collect(Collectors.toMap(x->x.getTemplate().getId(),Function.identity()));return templates.findByAccountIdAndActiveTrueOrderBySortOrderAscTitleAsc(aid).stream().map(t->checklistDto(t,byTemplate.get(t.getId()))).toList();}
 @Transactional public ChecklistItemDto createTemplate(Long aid,Long uid,ChecklistTemplateRequest r){Account a=society(aid);User u=user(uid);SocietyDailyChecklistTemplate t=templates.save(SocietyDailyChecklistTemplate.builder().account(a).title(r.getTitle().trim()).description(clean(r.getDescription())).sortOrder(r.getSortOrder()==null?0:r.getSortOrder()).createdBy(u).build());event(a,u,"CHECKLIST_TEMPLATE_CREATED","CHECKLIST_TEMPLATE",t.getId(),t.getTitle());return checklistDto(t,null);}
 @Transactional public ChecklistItemDto updateChecklist(Long aid,Long uid,Long templateId,LocalDate date,ChecklistUpdateRequest r){SocietyDailyChecklistTemplate t=templates.findByAccountIdAndId(aid,templateId).orElseThrow(()->new ResourceNotFoundException("Checklist item not found"));User u=user(uid);SocietyDailyChecklistEntry e=entries.findByAccountIdAndTemplateIdAndOperationDate(aid,templateId,date).orElseGet(()->SocietyDailyChecklistEntry.builder().account(t.getAccount()).template(t).operationDate(date).build());e.setCompleted(r.getCompleted());e.setNotes(clean(r.getNotes()));e.setCompletedBy(r.getCompleted()?u:null);e.setCompletedAt(r.getCompleted()?LocalDateTime.now():null);entries.save(e);event(t.getAccount(),u,"CHECKLIST_UPDATED","CHECKLIST_ENTRY",e.getId(),t.getTitle()+"="+r.getCompleted());return checklistDto(t,e);}
 @Transactional public void disableTemplate(Long aid,Long uid,Long id){SocietyDailyChecklistTemplate t=templates.findByAccountIdAndId(aid,id).orElseThrow(()->new ResourceNotFoundException("Checklist item not found"));t.setActive(false);templates.save(t);event(t.getAccount(),user(uid),"CHECKLIST_TEMPLATE_DISABLED","CHECKLIST_TEMPLATE",id,t.getTitle());}
 @Transactional(readOnly=true) public List<IncidentDto> listIncidents(Long aid){society(aid);return incidents.findByAccountIdOrderByOccurredAtDesc(aid).stream().map(this::incidentDto).toList();}
 @Transactional public IncidentDto createIncident(Long aid,Long uid,IncidentRequest r){Account a=society(aid);User u=user(uid);String severity=choice(r.getSeverity(),SEVERITIES,"severity");SocietyIncident x=incidents.save(SocietyIncident.builder().account(a).incidentNumber("INC-"+String.format("%05d",incidents.countByAccountId(aid)+1)).title(r.getTitle().trim()).description(r.getDescription().trim()).severity(severity).location(clean(r.getLocation())).occurredAt(r.getOccurredAt()).immediateAction(clean(r.getImmediateAction())).sensitive(Boolean.TRUE.equals(r.getSensitive())).createdBy(u).build());event(a,u,"INCIDENT_CREATED","INCIDENT",x.getId(),x.getIncidentNumber()+" "+severity);return incidentDto(x);}
 @Transactional public IncidentDto updateIncident(Long aid,Long uid,Long id,IncidentUpdateRequest r){SocietyIncident x=incidents.findByAccountIdAndId(aid,id).orElseThrow(()->new ResourceNotFoundException("Incident not found"));String status=choice(r.getStatus(),INCIDENT_STATUSES,"incident status");x.setStatus(status);x.setFollowUp(clean(r.getFollowUp()));if("CLOSED".equals(status)){x.setClosedAt(LocalDateTime.now());x.setClosedBy(user(uid));}else{x.setClosedAt(null);x.setClosedBy(null);}incidents.save(x);event(x.getAccount(),user(uid),"INCIDENT_UPDATED","INCIDENT",id,status);return incidentDto(x);}
 @Transactional(readOnly=true) public List<InspectionDto> listInspections(Long aid){society(aid);return inspections.findByAccountIdOrderByScheduledForDesc(aid).stream().map(this::inspectionDto).toList();}
 @Transactional public InspectionDto createInspection(Long aid,Long uid,InspectionRequest r){Account a=society(aid);User u=user(uid);SocietyInspection x=inspections.save(SocietyInspection.builder().account(a).title(r.getTitle().trim()).location(clean(r.getLocation())).scheduledFor(r.getScheduledFor()).checklist(clean(r.getChecklist())).createdBy(u).build());event(a,u,"INSPECTION_CREATED","INSPECTION",x.getId(),x.getTitle());return inspectionDto(x);}
 @Transactional public InspectionDto completeInspection(Long aid,Long uid,Long id,InspectionCompleteRequest r){SocietyInspection x=inspections.findByAccountIdAndId(aid,id).orElseThrow(()->new ResourceNotFoundException("Inspection not found"));String result=choice(r.getResult(),RESULTS,"inspection result");if("FAIL".equals(result)&&(r.getFailureAction()==null||r.getFailureAction().isBlank()))throw new ValidationException("Failure action is required for a failed inspection");x.setResult(result);x.setNotes(clean(r.getNotes()));x.setFailureAction(clean(r.getFailureAction()));x.setCompletedAt(LocalDateTime.now());x.setCompletedBy(user(uid));if(r.getWorkOrderId()!=null)x.setWorkOrder(workOrders.findByAccountIdAndId(aid,r.getWorkOrderId()).orElseThrow(()->new ResourceNotFoundException("Work order not found")));inspections.save(x);event(x.getAccount(),user(uid),"INSPECTION_COMPLETED","INSPECTION",id,result);return inspectionDto(x);}
 @Transactional(readOnly=true) public List<HandoverDto> listHandovers(Long aid){society(aid);return handovers.findByAccountIdOrderByCreatedAtDesc(aid).stream().map(this::handoverDto).toList();}
 @Transactional public HandoverDto createHandover(Long aid,Long uid,HandoverRequest r){Account a=society(aid);User u=user(uid);SocietyShiftHandover x=handovers.save(SocietyShiftHandover.builder().account(a).shiftDate(r.getShiftDate()).shiftName(r.getShiftName().trim()).openItems(clean(r.getOpenItems())).incidents(clean(r.getIncidents())).expectedVisitors(clean(r.getExpectedVisitors())).assetsHandedOver(clean(r.getAssetsHandedOver())).equipmentStatus(clean(r.getEquipmentStatus())).attendanceShortages(clean(r.getAttendanceShortages())).notes(clean(r.getNotes())).receiverName(clean(r.getReceiverName())).sender(u).build());event(a,u,"HANDOVER_CREATED","SHIFT_HANDOVER",x.getId(),x.getShiftName());return handoverDto(x);}
 @Transactional public HandoverDto acknowledgeHandover(Long aid,Long uid,Long id){SocietyShiftHandover x=handovers.findByAccountIdAndId(aid,id).orElseThrow(()->new ResourceNotFoundException("Handover not found"));x.setReceiver(user(uid));x.setAcknowledgedAt(LocalDateTime.now());handovers.save(x);event(x.getAccount(),x.getReceiver(),"HANDOVER_ACKNOWLEDGED","SHIFT_HANDOVER",id,x.getShiftName());return handoverDto(x);}
 @Transactional(readOnly=true) public List<DailyReportDto> listReports(Long aid){society(aid);return reports.findByAccountIdOrderByReportDateDescRevisionDesc(aid).stream().map(this::reportDto).toList();}
 @Transactional public DailyReportDto saveReport(Long aid,Long uid,ReportRequest r,boolean submit){Account a=society(aid);User u=user(uid);List<SocietyDailyReport> versions=reports.findByAccountIdAndReportDateOrderByRevisionDesc(aid,r.getReportDate());SocietyDailyReport current=versions.isEmpty()?null:versions.get(0);int revision=current==null?1:current.getRevision();if(current!=null&&!"DRAFT".equals(current.getStatus())){current=null;revision++;}Map<String,Object> snapshot=snapshot(aid,r.getReportDate());SocietyDailyReport x=current==null?SocietyDailyReport.builder().account(a).reportDate(r.getReportDate()).revision(revision).snapshotJson(write(snapshot)).build():current;x.setSummary(clean(r.getSummary()));x.setNextDayPriorities(clean(r.getNextDayPriorities()));x.setSnapshotJson(write(snapshot));if(submit){x.setStatus("SUBMITTED");x.setSubmittedBy(u);x.setSubmittedAt(LocalDateTime.now());}reports.save(x);event(a,u,submit?"DAILY_REPORT_SUBMITTED":"DAILY_REPORT_SAVED","DAILY_REPORT",x.getId(),r.getReportDate()+" revision="+revision);return reportDto(x);}
 @Transactional public DailyReportDto acknowledgeReport(Long aid,Long uid,Long id,AcknowledgeRequest r){SocietyDailyReport x=reports.findByAccountIdAndId(aid,id).orElseThrow(()->new ResourceNotFoundException("Daily report not found"));if(!"SUBMITTED".equals(x.getStatus()))throw new ValidationException("Only submitted reports can be acknowledged");x.setStatus("ACKNOWLEDGED");x.setAcknowledgedBy(user(uid));x.setAcknowledgedAt(LocalDateTime.now());x.setAdminComment(clean(r.getComment()));reports.save(x);event(x.getAccount(),x.getAcknowledgedBy(),"DAILY_REPORT_ACKNOWLEDGED","DAILY_REPORT",id,x.getReportDate().toString());return reportDto(x);}
 @Transactional(readOnly=true) public DashboardDto dashboard(Long aid,LocalDate date){society(aid);List<SocietyAttendance> ar=attendance.findByAccountIdAndAttendanceDate(aid,date);List<SocietyWorkOrder> wo=workOrders.findByAccountIdOrderByCreatedAtDesc(aid);List<SocietyComplaint> cr=complaints.findByAccountIdOrderByCreatedAtDesc(aid);List<ChecklistItemDto> cl=checklist(aid,date);List<SocietyDailyReport> rr=reports.findByAccountIdAndReportDateOrderByRevisionDesc(aid,date);LocalDateTime from=date.atStartOfDay(),to=date.plusDays(1).atStartOfDay();return DashboardDto.builder().date(date).attendanceRecorded(ar.size()).present(ar.stream().filter(x->Set.of("PRESENT","LATE","HALF_DAY","REPLACEMENT").contains(x.getStatus())).count()).absent(ar.stream().filter(x->"ABSENT".equals(x.getStatus())).count()).openWorkOrders(wo.stream().filter(x->!Set.of("COMPLETED","VERIFIED","CANCELLED").contains(x.getStatus())).count()).overdueWorkOrders(wo.stream().filter(x->x.getDueAt()!=null&&x.getDueAt().isBefore(LocalDateTime.now())&&!Set.of("COMPLETED","VERIFIED","CANCELLED").contains(x.getStatus())).count()).openComplaints(cr.stream().filter(x->!Set.of("RESOLVED","CLOSED").contains(x.getStatus())).count()).openIncidents(incidents.countByAccountIdAndStatusNot(aid,"CLOSED")).inspectionsDue(inspections.countByAccountIdAndScheduledForBetween(aid,from,to)).inspectionsFailed(inspections.countByAccountIdAndResult(aid,"FAIL")).handovers(handovers.countByAccountIdAndShiftDate(aid,date)).checklistTotal(cl.size()).checklistCompleted(cl.stream().filter(x->Boolean.TRUE.equals(x.getCompleted())).count()).reportStatus(rr.isEmpty()?"NOT_STARTED":rr.get(0).getStatus()).recentReports(reports.findByAccountIdOrderByReportDateDescRevisionDesc(aid).stream().limit(5).map(this::reportDto).toList()).build();}
 private Map<String,Object> snapshot(Long aid,LocalDate d){LocalDateTime from=d.atStartOfDay(),to=d.plusDays(1).atStartOfDay();List<SocietyAttendance> ar=attendance.findByAccountIdAndAttendanceDate(aid,d);List<SocietyWorkOrder> wo=workOrders.findByAccountIdOrderByCreatedAtDesc(aid);List<SocietyComplaint> cr=complaints.findByAccountIdOrderByCreatedAtDesc(aid);Map<String,Object> m=new LinkedHashMap<>();m.put("attendanceRecorded",ar.size());m.put("attendanceStatuses",ar.stream().collect(Collectors.groupingBy(SocietyAttendance::getStatus,Collectors.counting())));m.put("workOpened",wo.stream().filter(x->!x.getCreatedAt().isBefore(from)&&x.getCreatedAt().isBefore(to)).count());m.put("workCompleted",wo.stream().filter(x->x.getCompletedAt()!=null&&!x.getCompletedAt().isBefore(from)&&x.getCompletedAt().isBefore(to)).count());m.put("workOverdue",wo.stream().filter(x->x.getDueAt()!=null&&x.getDueAt().isBefore(to)&&!Set.of("COMPLETED","VERIFIED","CANCELLED").contains(x.getStatus())).count());m.put("complaintsReceived",cr.stream().filter(x->!x.getCreatedAt().isBefore(from)&&x.getCreatedAt().isBefore(to)).count());m.put("complaintsResolved",cr.stream().filter(x->x.getResolvedAt()!=null&&!x.getResolvedAt().isBefore(from)&&x.getResolvedAt().isBefore(to)).count());m.put("incidents",incidents.countByAccountIdAndOccurredAtBetween(aid,from,to));m.put("inspections",inspections.countByAccountIdAndScheduledForBetween(aid,from,to));m.put("handovers",handovers.countByAccountIdAndShiftDate(aid,d));m.put("checklistCompleted",checklist(aid,d).stream().filter(x->Boolean.TRUE.equals(x.getCompleted())).count());return m;}
 private ChecklistItemDto checklistDto(SocietyDailyChecklistTemplate t,SocietyDailyChecklistEntry e){return ChecklistItemDto.builder().templateId(t.getId()).title(t.getTitle()).description(t.getDescription()).sortOrder(t.getSortOrder()).entryId(e==null?null:e.getId()).completed(e!=null&&Boolean.TRUE.equals(e.getCompleted())).notes(e==null?null:e.getNotes()).completedBy(e==null||e.getCompletedBy()==null?null:e.getCompletedBy().getName()).completedAt(e==null?null:e.getCompletedAt()).build();}
 private IncidentDto incidentDto(SocietyIncident x){return IncidentDto.builder().id(x.getId()).incidentNumber(x.getIncidentNumber()).title(x.getTitle()).description(x.getDescription()).severity(x.getSeverity()).location(x.getLocation()).occurredAt(x.getOccurredAt()).status(x.getStatus()).immediateAction(x.getImmediateAction()).followUp(x.getFollowUp()).sensitive(x.getSensitive()).createdBy(x.getCreatedBy().getName()).closedAt(x.getClosedAt()).build();}
 private InspectionDto inspectionDto(SocietyInspection x){return InspectionDto.builder().id(x.getId()).title(x.getTitle()).location(x.getLocation()).scheduledFor(x.getScheduledFor()).completedAt(x.getCompletedAt()).result(x.getResult()).checklist(x.getChecklist()).notes(x.getNotes()).failureAction(x.getFailureAction()).workOrderId(x.getWorkOrder()==null?null:x.getWorkOrder().getId()).completedBy(x.getCompletedBy()==null?null:x.getCompletedBy().getName()).build();}
 private HandoverDto handoverDto(SocietyShiftHandover x){return HandoverDto.builder().id(x.getId()).shiftDate(x.getShiftDate()).shiftName(x.getShiftName()).openItems(x.getOpenItems()).incidents(x.getIncidents()).expectedVisitors(x.getExpectedVisitors()).assetsHandedOver(x.getAssetsHandedOver()).equipmentStatus(x.getEquipmentStatus()).attendanceShortages(x.getAttendanceShortages()).notes(x.getNotes()).sender(x.getSender().getName()).receiverName(x.getReceiverName()).acknowledgedAt(x.getAcknowledgedAt()).acknowledgedBy(x.getReceiver()==null?null:x.getReceiver().getName()).createdAt(x.getCreatedAt()).build();}
 private DailyReportDto reportDto(SocietyDailyReport x){return DailyReportDto.builder().id(x.getId()).reportDate(x.getReportDate()).revision(x.getRevision()).status(x.getStatus()).summary(x.getSummary()).nextDayPriorities(x.getNextDayPriorities()).snapshot(read(x.getSnapshotJson())).submittedBy(x.getSubmittedBy()==null?null:x.getSubmittedBy().getName()).submittedAt(x.getSubmittedAt()).acknowledgedBy(x.getAcknowledgedBy()==null?null:x.getAcknowledgedBy().getName()).acknowledgedAt(x.getAcknowledgedAt()).adminComment(x.getAdminComment()).build();}
 private String write(Map<String,Object> value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("Unable to build report snapshot",e);}} private Map<String,Object> read(String value){try{return json.readValue(value,new TypeReference<>(){});}catch(Exception e){return Map.of();}}
 private Account society(Long id){return accounts.findById(id).filter(x->x.getAccountType()==AccountType.SOCIETY&&Boolean.TRUE.equals(x.getActive())).orElseThrow(()->new ResourceNotFoundException("Society not found"));} private User user(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));} private String choice(String v,Set<String> allowed,String field){String n=v==null?"":v.trim().toUpperCase();if(!allowed.contains(n))throw new ValidationException("Invalid "+field);return n;} private String clean(String v){return v==null||v.isBlank()?null:v.trim();} private void event(Account a,User u,String action,String type,Long id,String details){audit.save(SocietyAuditEvent.builder().account(a).actor(u).action(action).entityType(type).entityId(id).details(details).build());}
}
